{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Trihexyphenidyl, a tertiary amine anticholinergic with a cyclohexyl-phenyl core, is shown by PET to penetrate the BBB easily, supporting CNS access for the query's similar tertiary amine and cyclohexyl-phenyl pharmacophore.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Adiphenine, a diethylaminoethyl ester of a diphenylacetic acid, reaches brain concentrations 4–15 times higher than blood in rodents, demonstrating that this tertiary amine ester chemotype crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Naftidrofuryl, a tertiary amine ester, reaches maximum brain concentration 5 min after intraperitoneal dosing in rats, indicating rapid BBB penetration for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Methylphenidate, a tertiary amine ester, shows high brain-to-plasma ratios (10.6–11.2) in rats and brain uptake by PET, supporting CNS penetration of ionizable tertiary amine esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Glycopyrronium, a quaternary ammonium analogue, has unmeasurable CSF levels in humans, but its permanent positive charge is a decisive non-transferable liability absent in the query's neutralizable tertiary amine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "3-[18F]FEPB, a tertiary amine benzilate ester, shows low non-receptor-mediated brain uptake in rodents; however, its benzilate/tropane scaffold and lower similarity limit transfer to the oxybutynin-like query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Several muscarinic PET ligands (scopolamine, QNB, benztropine, TRB) showed relatively low brain uptake; these rigid bicyclic amine/benzilate structures are less transferable to the flexible open-chain tertiary amine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass: the query (oxybutynin) is a neutralizable tertiary amine antimuscarinic ester. Direct CNS-penetration evidence from close tertiary amine anticholinergic/ester analogues (trihexyphenidyl, adiphenine, naftidrofuryl, methylphenidate) outweighs the poor CNS uptake seen for quaternary glycopyrronium and rigid benzilate/tropane ligands, which lack the query's flexible tertiary amine and cyclohexyl-phenyl ester features.",
  "evidence_gaps": [
    "No direct CSF or brain-to-plasma measurement for the query itself is present; prediction relies on close analogues.",
    "The highest-similarity record is a quaternary ammonium compound whose permanent charge prevents direct extrapolation.",
    "Some tertiary amine muscarinic ligands show low brain uptake, so the exact structural determinants of penetration are not fully resolved; however, the open-chain tertiary amine ester and cyclohexyl-phenyl features align with penetrant analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

